check:
from dependency_order import order

graph = {"d":["b","b"],"c":["a"],"b":[],"e":["d","c"]}
assert order(graph) == ["a","b","c","d","e"]
assert graph["d"] == ["b","b"]
assert order({"a":["b"],"z":[]}) == ["b","a","z"]
assert order({}) == []
for graph in [{"a":["a"]}, {"a":["b"],"b":["a"],"free":[]}]:
    try:
        order(graph)
    except ValueError:
        pass
    else:
        raise AssertionError("expected cycle")

from roman import encode

ones = ["","I","II","III","IV","V","VI","VII","VIII","IX"]
tens = ["","X","XX","XXX","XL","L","LX","LXX","LXXX","XC"]
hundreds = ["","C","CC","CCC","CD","D","DC","DCC","DCCC","CM"]
for n in range(1,4000):
    assert encode(n) == "M"*(n//1000) + hundreds[n//100%10] + tens[n//10%10] + ones[n%10]
for n in (-1,0,4000):
    try:
        encode(n)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")
